        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return obj[0], obj[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(target, sx, sy):
        tx, ty = pos2(target, (sx, sy))
        return [sgn(tx - sx), sgn(ty - sy)]

    def step_away(target, sx, sy):
